/**
 * Button (issue #11) — the first Augur-owned component.
 *
 * shadcn-compatible API, Augur-owned styling: a native `<button>`
 * styled exclusively through the semantic role custom properties
 * delivered by `@augurproject/design-system/styles.css` (see `./button.css`).
 * React 19 style: a plain function component; `ref` forwards through
 * props (no forwardRef).
 *
 * Contracts (consumer view: docs "Button" page; component contract:
 * `docs/components.md` in this package):
 *
 *   - `type` defaults to "button" — a deliberate deviation from
 *     upstream shadcn, which leaves the browser's "submit" default.
 *     Forms opt into submission explicitly.
 *   - Disabled: native `disabled`, reduced-contrast but present label,
 *     `cursor: not-allowed` (the disabled treatment).
 *   - Loading (`loading`): non-interactive, `aria-busy="true"`, label
 *     kept in the DOM but hidden from eyes and assistive technology so
 *     the button keeps its width; a reduced-motion-safe spinner and a
 *     visually hidden "Loading" status carry the state. The action
 *     color does not change.
 *
 *   - Link rendering (`asChild`, issue #97): shadcn's Slot pattern.
 *     `<Button asChild><a href="/protocol/">How it works</a></Button>`
 *     merges the button classes onto the single child element and
 *     renders nothing else, so the child keeps its own semantics (a link
 *     navigates; it is not a button). `type`, `disabled`, and `loading`
 *     do not apply to a link and are not accepted with `asChild`.
 *
 * Keyboard focus needs no CSS here: the theme contract's shared
 * `:focus-visible` rule (2px ring, 2px offset, `--ring` color) applies
 * to every element, including this one.
 */

import "./button.css";
import type { ComponentProps } from "react";
import { Slot } from "radix-ui";
import type { ButtonSize, ButtonVariant } from "./button-variants";
import { buttonVariants } from "./button-variants";
import { cx } from "@/lib/utils";

export { buttonVariants } from "./button-variants";

type ButtonStyleProps = {
  /** Visual intent. The default variant is the view's one green signal. */
  variant?: ButtonVariant;
  /** Control size. Default "md". */
  size?: ButtonSize;
};

/** Native `<button>` rendering. */
export type ButtonElementProps = ComponentProps<"button"> &
  ButtonStyleProps & {
    asChild?: false;
    /** Pending state: non-interactive, width-preserving, aria-busy. */
    loading?: boolean;
  };

/** Slot rendering: the button classes are merged onto the single child
 * element (typically an `<a>`), which keeps its own semantics. */
export type ButtonAsChildProps = Omit<ComponentProps<"button">, "type" | "disabled"> &
  ButtonStyleProps & {
    asChild: true;
    loading?: never;
  };

export type ButtonProps = ButtonElementProps | ButtonAsChildProps;

export function Button(props: ButtonProps) {
  if (props.asChild) {
    const { asChild: _asChild, variant, size, className, ...rest } = props;
    return <Slot.Root {...rest} className={cx(buttonVariants({ variant, size }), className)} />;
  }
  const {
    asChild: _asChild,
    variant,
    size,
    loading = false,
    disabled = false,
    type,
    className,
    children,
    ...rest
  } = props;
  return (
    <button
      {...rest}
      type={type ?? "button"}
      disabled={disabled || loading}
      aria-busy={loading || undefined}
      className={cx(buttonVariants({ variant, size }), className)}
    >
      <span className="aug-button-label" aria-hidden={loading || undefined}>
        {children}
      </span>
      {loading ? (
        <span className="aug-button-spinner" aria-hidden="true">
          <svg
            className="aug-button-spinner-icon"
            viewBox="0 0 16 16"
            width="16"
            height="16"
            aria-hidden="true"
          >
            <circle
              cx="8"
              cy="8"
              r="6.5"
              fill="none"
              stroke="currentColor"
              strokeWidth="2"
              strokeLinecap="round"
              strokeDasharray="29 12"
            />
          </svg>
        </span>
      ) : null}
      {loading ? <span className="aug-button-visually-hidden">Loading</span> : null}
    </button>
  );
}

/**
 * Variant and size class mapping for Button (issue #11).
 *
 * Augur owns this API but keeps it shadcn-shaped: `buttonVariants` is
 * the plain-function analog of the upstream `cva` call — callable with
 * `{ variant, size }` and returning the full class string, including
 * the control typography role, so class-only consumers (and the future
 * registry source path, issue #16) get the same result by applying the
 * classes to a native `<button>`. No class-variance-authority
 * dependency: the matrix is small and the package's runtime
 * dependencies stay at the font packages.
 *
 * Classes resolve color exclusively through the semantic role custom
 * properties in `src/styles/theme.css`. Geometry values in
 * `button.css` are structural constants (spacing, control heights,
 * radius), not emitted tokens; see `docs/components.md` in this
 * package for the component contract.
 */

import "./button.css";

/** Visual intent of the button. shadcn-compatible set, Augur-owned. */
export type ButtonVariant =
  | "default"
  | "secondary"
  | "destructive"
  | "outline"
  | "ghost"
  | "link";

/** Control size. `xl` is 48px with 16/24 labels (adopted from augur.net). */
export type ButtonSize = "sm" | "md" | "lg" | "xl";

export interface ButtonVariantsProps {
  variant?: ButtonVariant;
  size?: ButtonSize;
}

const VARIANT_CLASSES: Record<ButtonVariant, string> = {
  default: "aug-button--default",
  secondary: "aug-button--secondary",
  destructive: "aug-button--destructive",
  outline: "aug-button--outline",
  ghost: "aug-button--ghost",
  link: "aug-button--link",
};

const SIZE_CLASSES: Record<ButtonSize, string> = {
  sm: "aug-button--sm",
  md: "aug-button--md",
  lg: "aug-button--lg",
  xl: "aug-button--xl",
};

/** Full class string for the given variant and size (defaults: md). */
export function buttonVariants(props: ButtonVariantsProps = {}): string {
  const variant = props.variant ?? "default";
  const size = props.size ?? "md";
  return `aug-button augur-type-control ${VARIANT_CLASSES[variant]} ${SIZE_CLASSES[size]}`;
}

/*
 * Button styles (issue #11).
 *
 * Color: ONLY semantic role custom properties from ../../styles/roles.css
 * (which references generated tokens). No raw color values, no new
 * custom properties.
 *
 * Geometry: spacing and radius consume the generated tokens
 * (--augur-spacing-*, --augur-rounded-control — issues #45/#51); control
 * heights remain adopted structural constants. The component contract
 * for this slice lives in ../../docs/components.md.
 *
 * Every rule sits in `@layer augur`; this file depends only on the
 * theme (`theme.css`).
 */

@layer augur {

/* Margin reset at zero specificity (issue #97): it clears user-agent
   button margins but never outranks a consumer's layout margin, whatever
   the stylesheet order. */
:where(.aug-button) {
  margin: 0;
}

.aug-button {
  position: relative;
  box-sizing: border-box;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--augur-spacing-sm); /* space.sm: label-to-icon gap */
  height: 36px; /* control.height.md */
  padding: 0 var(--augur-spacing-lg); /* md control padding */
  border: 1px solid transparent; /* keeps the box equal across variants */
  border-radius: var(--augur-rounded-control); /* radius.control: 0px */
  vertical-align: middle;
  white-space: nowrap;
  cursor: pointer;
  text-decoration: none;
  background-color: var(--primary);
  color: var(--primary-foreground);
}

/* Sizes: adopted values as structure (sm 32/12, lg 40/24). */
.aug-button--sm {
  height: 32px;
  padding: 0 var(--augur-spacing-md);
}

.aug-button--lg {
  height: 40px;
  padding: 0 var(--augur-spacing-xl);
}

/* xl: 48px with 16/24 labels, adopted from augur.net for prominent
   actions. The doubled class outranks the 14/20 control role class
   whatever the stylesheet order. */
.aug-button.aug-button--xl {
  height: 48px;
  padding: 0 var(--augur-spacing-xl);
  font-size: 16px;
  line-height: 24px;
}

/*
 * Filled variants. default = action-primary pairing (Deep + White
 * light, Green + Navy dark — the view's one green signal); secondary
 * sits on the quiet surface; destructive uses the strongest neutral
 * pairing (the brand defines no danger hue, so the
 * label carries the meaning).
 */
.aug-button--secondary {
  background-color: var(--secondary);
  color: var(--secondary-foreground);
}

.aug-button--destructive {
  background-color: var(--destructive);
  color: var(--destructive-foreground);
}

/* Surface variants: quiet by default; the theme's neutral
   hover/highlight surface (accent) on hover. */
.aug-button--outline {
  background-color: transparent;
  border-color: var(--input);
  color: var(--foreground);
}

.aug-button--ghost {
  background-color: transparent;
  color: var(--foreground);
}

/* Link: quiet text action. Deliberately NOT action-colored — a view
   has one green signal (primary action, focus), and text links are not
   it (the surface-step mapping in docs/components.md). */
.aug-button--link {
  background-color: transparent;
  color: var(--foreground);
}

/* Surface variants hover onto the neutral highlight surface; the
   outline's edge also steps up to the control hover edge. */
.aug-button--outline:hover:not(:disabled),
.aug-button--ghost:hover:not(:disabled) {
  background-color: var(--accent);
  color: var(--accent-foreground);
}

.aug-button--outline:hover:not(:disabled) {
  border-color: var(--input-hover);
}

/* Filled variants step to a neighbouring palette color and keep their
   own family, so a hovered primary never reads as disabled. Existing
   palette steps only; no alpha tints. The default (primary) hover is
   Green in light and the darker Green hover step in dark. */
.aug-button--default:hover:not(:disabled) {
  background-color: var(--primary-hover);
  color: var(--primary-hover-foreground);
}

.aug-button--secondary:hover:not(:disabled) {
  background-color: var(--secondary-hover);
  color: var(--secondary-foreground);
}

.aug-button--destructive:hover:not(:disabled) {
  background-color: var(--destructive-hover);
  color: var(--destructive-foreground);
}
/* Pressed: the default button takes its own pressed role (the Navy
   inversion in light, the Green pressed step in dark); the other
   variants invert to foreground on background. */
.aug-button--default:active:not(:disabled) {
  background-color: var(--primary-active);
  color: var(--primary-active-foreground);
}

.aug-button--destructive:active:not(:disabled),
.aug-button--secondary:active:not(:disabled),
.aug-button--outline:active:not(:disabled),
.aug-button--ghost:active:not(:disabled) {
  background-color: var(--foreground);
  color: var(--background);
}

.aug-button--link:hover:not(:disabled) {
  text-decoration: underline;
  text-underline-offset: 0.2em;
  text-decoration-thickness: 2px;
}

/*
 * Disabled: non-interactive via the
 * native attribute, reduced-contrast label that remains present and
 * readable in the DOM, never color-alone. WCAG 1.4.3 exempts disabled
 * controls from contrast minimums.
 */
.aug-button:disabled {
  cursor: not-allowed;
  opacity: 0.5;
}

/*
 * Loading: the label stays in the DOM (width preserved)
 * but is hidden from eyes and assistive technology; the spinner
 * overlays, centered; the accessible name becomes the visually hidden
 * "Loading" status rendered by the component.
 */
.aug-button[aria-busy="true"] .aug-button-label {
  visibility: hidden;
}

.aug-button-spinner {
  position: absolute;
  inset: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  pointer-events: none;
}

.aug-button-spinner-icon {
  display: block;
  /* Static pending indicator. A future functional animation requires review. */
  animation: none;
}

/* Visually hidden loading status (component-scoped utility). */
.aug-button-visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}

/* Adopted touch target minimum; desktop size variants remain intact. */
@media (pointer: coarse) {
  .aug-button { min-height: 44px; min-width: 44px; }
}

} /* @layer augur */
